CREATE TABLE IF NOT EXISTS domain_outbox(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,command_key VARCHAR(160) NOT NULL UNIQUE,target_name VARCHAR(30) NOT NULL,action_name VARCHAR(60) NOT NULL,payload JSON NOT NULL,aggregate_key VARCHAR(200) NOT NULL,INDEX ix_domain_aggregate(aggregate_key,id,published_at),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),published_at DATETIME(3),claimed_until DATETIME(3),INDEX ix_domain_pending(published_at,claimed_until,id));
CREATE TABLE IF NOT EXISTS domain_inbox(command_key VARCHAR(160) NOT NULL PRIMARY KEY,processed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS domain_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT,action VARCHAR(64) NOT NULL,entity_id BIGINT,reason VARCHAR(1500),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
